                    case TERRAIN_HILL:
                    case TERRAIN_LAKE:
                    case TERRAIN_LAVA_LAKE:
                    case TERRAIN_MANDRAKE:
                    case TERRAIN_MOUND:
                    case TERRAIN_MOUNTAIN:
                    case TERRAIN_OAK_TREE:
                    case TERRAIN_PINE_TREE:
                    case TERRAIN_SAND_DUNE:
                    case TERRAIN_SAND_PIT:
                    case TERRAIN_STALAGMITE:
                    case TERRAIN_STUMP:
                    case TERRAIN_TAR_PIT:
